```python
def is_palindrome(n):
    return str(n) == str(n)[::-1]

def reverse_and_add_steps(n):
    count = 0
    while count < 6:
        if is_palindrome(n):
            return count
        n = n + int(str(n)[::-1])
        count += 1
    return count if count == 6 else None

total_sum = 0
for i in range(10, 100):
    if not is_palindrome(i):
        if reverse_and_add_steps(i) == 6:
            total_sum += i

print(total_sum)
```
